    public function toAttributes(): PlatformIdentityAttributes
    {
        $att = new PlatformIdentityAttributes();
        $this->writeUidTo($att);
        $this->writeUserTo($att);
        $this->writeRelyingPartyTo($att);
        $this->writeTrustedClientTo($att);
        $this->writeRolesTo($att);
        $this->writeVersionTo($att);
        return $att;
    }
    public function unset(string $field): void
    {
        if (isset(self::UNSETS[$field])) {
            call_user_func([$this, self::UNSETS[$field]]);
        }
    }
    public function withDefaults(): PlatformIdentityUpdateResult
    {
        $this->withDefaultUid();
        $this->withDefaultUser();
        $this->withDefaultRelyingParty();
        $this->withDefaultTrustedClient();
        $this->withDefaultRoles();
        $this->withDefaultVersion();
        return $this;
    }
}
